<form method="post" action="/partner/trees/{{ $tree->id }}/monitoring" enctype="multipart/form-data" class="form-stack">@csrf @if($log)<input type="hidden" name="monitoring_id" value="{{ $log->id }}">@endif<div class="form-grid"><label>Tanggal pemantauan<input type="date" name="observed_at" value="{{ $log?->observed_at?->toDateString() ?? today()->toDateString() }}" min="{{ $tree->planting->planted_at->toDateString() }}" max="{{ today()->toDateString() }}" required></label><label>Tinggi pohon (cm)<input type="number" step="0.1" name="height" min="0" max="100000" value="{{ $log?->height }}" required></label></div><label>Kondisi kesehatan<select name="health" required>@foreach(['healthy'=>'Sehat','care'=>'Perlu perawatan','dead'=>'Mati'] as $key=>$label)<option value="{{ $key }}" @selected($log?->health===$key)>{{ $label }}</option>@endforeach</select></label><label>Catatan perawatan<textarea name="care_note" rows="3" required>{{ $log?->care_note }}</textarea></label><label>Foto kondisi terbaru<input name="photo" type="file" accept="image/jpeg,image/png,image/webp" required><small>JPG, PNG, WebP · maksimal 5 MB</small></label><button class="button">Kirim Log Monitoring →</button></form>